    "segments": [
      {
        "start": 0,
        "end": 1.28,
        "text": "所有出来你可能不信"
      },
      {
        "start": 1.28,
        "end": 2.72,
        "text": "我一个不会拍视频的人"
      },
      {
        "start": 2.72,
        "end": 3.76,
        "text": "昨天就来当导演"
      },
      {
        "start": 3.76,
        "end": 4.76,
        "text": "拍了这么短剧"
      },
      {
        "start": 4.76,
        "end": 6.36,
        "text": "普通人也能当导演的秘密"
      },
      {
        "start": 6.36,
        "end": 7.8,
        "text": "今天特体给你拔明白"
      },
      {
        "start": 7.8,
        "end": 9.24,
        "text": "怎么把你脑海底的想法"
      },
      {
        "start": 9.24,
        "end": 10.64,
        "text": "直接变成能开的短剧"
      },
      {
        "start": 10.64,
        "end": 11.92,
        "text": "我用的这个工具叫做"
      },
      {
        "start": 11.92,
        "end": 12.72,
        "text": "小雲却AI"
      },
      {
        "start": 12.72,
        "end": 13.84,
        "text": "它可是头一个搭载"
      },
      {
        "start": 13.84,
        "end": 14.84,
        "text": "实在是2.0的"
      },
      {
        "start": 14.84,
        "end": 15.64,
        "text": "视频Agent"
      },
      {
        "start": 15.64,
        "end": 17.36,
        "text": "出来的画面不管镜头似滑"
      },
      {
        "start": 17.36,
        "end": 18.52,
        "text": "运气还特别专业"
      },
      {
        "start": 18.52,
        "end": 19.56,
        "text": "完全就不是那种"
      },
      {
        "start": 19.56,
        "end": 20.84,
        "text": "能弄住到几倍的东西"
      },
      {
        "start": 20.84,
        "end": 22.2,
        "text": "超多也简单到离谱"
      },
      {
        "start": 22.2,
        "end": 23.16,
        "text": "打开小雲却"
      },
      {
        "start": 23.16,
        "end": 24.12,
        "text": "先短剧Agent"
      },
      {
        "start": 24.12,
        "end": 25.56,
        "text": "它就想把直接扔进去"
      },
      {
        "start": 25.56,
        "end": 36.16,
        "text": "把你选举本比路我就说一句"
      },
      {
        "start": 36.16,
        "end": 37.4,
        "text": "直接给你把剧本"
      },
      {
        "start": 37.4,
        "end": 38.48,
        "text": "真的明明白白"
      },
      {
        "start": 38.48,
        "end": 39.52,
        "text": "最绝的是什么"
      },
      {
        "start": 39.52,
        "end": 40.76,
        "text": "你不用自己造出材"
      },
      {
        "start": 40.76,
        "end": 41.64,
        "text": "不用做人生"
      },
      {
        "start": 41.64,
        "end": 43.16,
        "text": "小雲却能直接给你生成"
      },
      {
        "start": 43.16,
        "end": 45,
        "text": "举本你所有角色的真正习下"
      },
      {
        "start": 45,
        "end": 45.8,
        "text": "不同的场景"
      },
      {
        "start": 45.8,
        "end": 47.2,
        "text": "还有不同的装够合线"
      },
      {
        "start": 47.2,
        "end": 48.12,
        "text": "方便到离谱"
      },
      {
        "start": 48.12,
        "end": 49.6,
        "text": "将你们看成品效果"
      },
      {
        "start": 52.12,
        "end": 53.36,
        "text": "早这么过来"
      },
      {
        "start": 53.36,
        "end": 55.12,
        "text": "还能少受点罪"
      },
      {
        "start": 55.12,
        "end": 60.92,
        "text": "你敢下毒"
      },
      {
        "start": 60.92,
        "end": 61.56,
        "text": "一句话"
      },
      {
        "start": 61.56,
        "end": 63.16,
        "text": "就能把你脑洞变成视频"
      },
      {
        "start": 63.16,
        "end": 64.4,
        "text": "这效果你打几份"
      },
      {
        "start": 64.4,
        "end": 65.4,
        "text": "评论局聊聊"
      }
    ],
